-- Generated by scripts/letters.ts from i18n/frFR/letters/: edit those, not this file.
-- letterTexts[id] = { greeting, body = { paragraph, ... }, signoff (its lines), ps = { paragraph, ... } }
local _, ns = ...
ns.letterTexts = {
  [1] = { greeting = "$N,", body = { "Je connaissais le nom d'Edwin VanCleef bien avant ses crimes. Hurlevent compte des murs qu'il a élevés de ses mains. Je suis soulagé que ce soit fini, et je n'ai pris aucun plaisir à vous le demander.", "Furlbrow voudrait rentrer chez lui avec sa famille. J'ai dû lui répondre : pas encore. Il voulait une date à noter, et je n'ai pas pu lui en donner. Il nous faut toujours des hommes sur les routes.", "La garde de nuit s'est passée sans alerte. Je ne m'y fie pas encore, et j'ai dit aux hommes de ne pas s'y fier non plus.", "Vous avez ma reconnaissance et celle de la milice. Je voulais que vous l'appreniez de moi." }, signoff = "Gryan Stoutmantle\nLa milice du peuple" },
  [2] = { greeting = "$gCher:Chère; $N,", body = { "Le mémorial est achevé, me dit-on, et le maître-maçon Marblesten est satisfait du granit d'Alterac que vous lui avez rapporté. J'avais demandé à notre roi ce que la guerre allait nous coûter. Il m'a répondu par du granit. Au maçon, je n'ai demandé qu'une chose : si le nom de Sully était gravé assez profondément pour rester lisible quand la pierre commencerait à s'user. La question est peut-être sotte. Elle comptait pour moi.", "J'ai rangé la lettre de Sully plusieurs fois. Chaque fois, l'un des garçons me demande ce que son père a écrit, et je la ressors. Le petit Edgar sait où je m'arrête, maintenant, et il m'attend là avant que je tourne la page.", "Cette lettre contient des choses que Sully ne m'a jamais dites à la maison. Il est étrange de les lire aujourd'hui, de sa main. J'aurais voulu pouvoir lui répondre.", "Merci de nous l'avoir rapportée. Je n'aurais pas supporté de perdre cela aussi." }, signoff = "Avec ma gratitude,\nSara Balloo" },
  [3] = { greeting = "$C,", body = { "La tête de Ramstein est au mur. Les chiens avalent de la pourriture vivante sans se plaindre. Ils refusent de manger sous cette tête. J'ai déplacé leurs gamelles.", "J'ai traqué Ramstein pendant des mois avant qu'il se réfugie dans Stratholme. L'avoir ici n'a rien arrangé à l'état de la ferme. Je n'y comptais pas. Je voulais sa mort, et vous y avez veillé.", "À votre arrivée à la ferme, vous n'étiez qu'$gun imbécile:une imbécile;. Vous voilà parmi mes champions. Je le mets par écrit parce que vous ne le croiriez pas autrement. Tâchez de ne pas laisser cela enfler ce qui vous tient lieu de tête.", "Voilà qui est fait." }, signoff = "Nathanos" },
  [4] = { greeting = "$N,", body = { "Ma mère a été heureuse d'apprendre que tu avais rencontré Cairne, mon enfant, et sa première pensée a été de savoir si tu avais mangé avant de monter là-haut. Je n'ai pas su lui répondre, et elle trouve qu'un chef devrait savoir ce genre de choses.", "Elle va encore chercher elle-même son eau au puits. Quand j'ai proposé de porter sa cruche, elle m'a demandé si un chef n'avait rien de mieux à faire, et quand je lui ai dit que toi, tu l'avais portée pour elle, elle m'a répondu que, le temps de le dire, j'aurais déjà pu aller chercher l'eau moi-même.", "Baine m'a fait parvenir des nouvelles de toi, et je les ai lues aux autres, près du feu. Les petits me les ont fait relire deux fois, et depuis, ils parlent des Rites chaque soir.", "Ma mère trouve que cette lettre a trop d'angles, comme les totems que je taille. Je lui ai dit que tu la lirais quand même." }, signoff = "Marche avec la Terre-mère,\nChef Hawkwind" },
  [5] = { greeting = "$gGamin:Gamine;,", body = { "La lentille est montée, le télescope marche, et les bottes sont de retour en rayon. Les clients ont arrêté de demander où elles étaient. Le meilleur silence que j'aie jamais payé.", "Écoute. Dizzywig a classé ta paie dans les frais de transport. Je lui ai fait corriger ça. Un chargement ne va pas tout seul dans un camp de pirates pour en ressortir avec les bonnes caisses. D'après mes comptes, je te dois donc la différence. Alors Dizzywig corrige les comptes. Pas la différence, $ggamin:gamine;. Les comptes.", "À Cabestan, tout le monde promet. Quatre-vingt-dix-neuf sur cent reviennent avec une histoire pour expliquer pourquoi ils n'ont pas pu. Toi, tu m'as rapporté mes bottes. Dans mon métier, c'est plus rare que l'or, et je m'y connais." }, signoff = "Gazlowe", ps = { "P.-S. Les pirates sont revenus sur la plage. Je leur ai envoyé une facture." } },
  [6] = { greeting = "$gMon cher:Ma chère; $N !", body = { "Bangalash ! Tout le camp en crie encore à table, le soir ! Sire Erlgadin jure que sa panthère était la proie la plus coriace, et Ajeck ne veut pas en entendre un mot. J'ai dû déplacer la bouilloire deux fois pour la sauver de leurs démonstrations.", "Erlgadin, Ajeck et moi avons tous beaucoup à dire sur ce tigre que vous avez abattu ! Il y avait une éternité que je guettais ce diable blanc, et j'ai bien gagné le droit d'en dire un mot !", "Barnil a lu mon récit de la chasse et m'a demandé quelle place vous y teniez. Excellente question ! Je me suis si bien emballé sur mes propres tentatives que je vous avais complètement oublié. C'est arrangé : vous y êtes, et à la place qui vous revient !", "Sacrément bien joué ! À votre santé, nom d'une pipe ! À votre santé !" }, signoff = "Hemet Nesingwary" },
  [7] = { greeting = "Le bonjour de la grotte, $N !", body = { "Je suis toujours là où tu m'as trouvé. Je me sens tout à fait rétabli, promis. Enfin, presque. Il reste beaucoup d'araignées Tissebois entre le reste de Sombrevallon et moi, et un elfe raisonnable attend qu'elles aient l'air occupées.", "Dirania me fait dire que je suis assez remis pour rentrer à pied. Elle me rappelle aussi, chaque fois, qu'elle m'avait mis en garde contre ces araignées. Bon, elle n'a pas tort.", "Avant, j'allais la voir chaque jour à la même heure. Maintenant, elle sait où je suis du matin au soir, et je crois qu'elle préfère ça.", "Je m'attire toujours des ennuis, et quelqu'un réussit toujours à m'en sortir. D'habitude, c'est Dirania. Cette fois, c'était toi, avec cinq minutes pour y arriver. Merci." }, signoff = "Ton ami,\nIverron" },
  [8] = { greeting = "$N,", body = { "Le fruit que vous avez trouvé est la chose la plus intéressante de mon camp. Je le garde enveloppé, bien à l'écart de la terre, tant que je n'aurai pas compris ce qui s'est passé entre les deux. La faute en revient-elle au fruit, ou à la terre de Teldrassil ? Je préférerais que ce soit au fruit.", "Les graines de sylvain sont dans la terre spéciale, avec la terre rare que vous avez apportée de Dolanaar, et je vais les voir plus souvent qu'il n'est utile. On dit que la graine guettée met deux fois plus de temps à lever. Je n'ai constaté ni cela ni le contraire.", "Ce que je sais : la plante qui a porté ce fruit est une étrangère ici. Sa graine est peut-être venue de très loin. Ce que j'ignore : presque tout le reste. C'est une situation merveilleuse.", "Vous avez l'œil, $N. Merci de me l'avoir prêté." }, signoff = "Respectueusement,\nDenalan" },
  [9] = { greeting = "$N !", body = { "Je l'ai fait !! J'ai bu jusqu'à la dernière goutte, je suis passée juste devant la maison, et personne n'a rien vu. Rien du tout ! J'entendais mes propres pas, et j'étais sûre que tout le vignoble les entendait aussi.", "Tommy Joe était à la rivière, là où il est toujours. Évidemment, il ne me voyait pas non plus, alors j'ai dû dire son nom, et il a sursauté si haut que j'ai cru qu'il allait tomber à l'eau. Et puis il a ri, et moi aussi, et nous avons parlé jusqu'à ce que je revoie mes mains. J'ai couru jusqu'à la maison.", "Je sais que c'était mal de tromper ma famille. Je le referais sans hésiter !", "Je ne peux même pas remercier monsieur Pestle ni Mamie Stonefield, puisque je ne suis pas censée les connaître !", "Vous avez porté ma lettre à Tommy Joe. Celle-ci est pour vous." }, signoff = "Avec tout mon amour (pas ce genre d'amour-là, hein !),\nM." },
  [10] = { greeting = "$gMon petit:Ma petite; $N,", body = { "Le collier est revenu à sa place. Je dors avec. Que les kobolds viennent essayer.", "Ce Billy Maclure raconte à qui veut l'entendre que ma tourte était la meilleure qu'il ait jamais mangée. Bien sûr qu'elle l'était. Là n'est pas la question. La question, c'est qu'il m'a pris mon collier et qu'il a eu de la tourte pour sa peine, et maintenant la moitié de la forêt connaît ma tourte mieux que mon nom.", "Je t'ai donné les gants de mon mari parce qu'ils ne servaient à personne, pendus au crochet près de la porte. Il disait toujours qu'ils portaient chance, et puis il est parti pour sa dernière campagne sans eux. J'ai longtemps regardé ce crochet. Mieux vaut qu'ils passent la porte avec quelqu'un.", "Merci, va. Tu as bel et bien réchauffé le cœur d'une pauvre veuve, mais je le nierai devant n'importe quel Maclure." }, signoff = "Tatie Bernice", ps = { "P.-S. Je n'ai rien mis dans la tourte de Billy. J'y ai pensé." } },
  [11] = { greeting = "Bien le bonjour, $N !", body = { "Mon frère dit que la Shimmer Stout met plein d'étoiles dans les yeux et qu'avec elle, il y voit dans le noir. Le montagnard Kadrell m'a écrit de Thelsamar : elle donne les jambes légères, et il a l'impression de pouvoir voler. Un brasseur pourrait vivre de mots pareils, et c'est presque ce que je fais. Merci de la leur avoir portée, $gmon gars:ma fille;.", "Seulement voilà : elle n'est pas parfaite. Une stout qui donne à un nain l'impression de voler est une bonne stout. Une stout parfaite lui garde les pieds sur terre et le rend content d'y être. La chatoyante donne la bonne note. C'est le malt en dessous qui ne va pas, trop doux ou pas assez sombre, et j'ai trois petits brassins en route pour le savoir.", "Le brassage, j'ai ça dans le sang, et le sang est patient. J'y arriverai." }, signoff = "Rejold Barleybrew" },
  [12] = { greeting = "$N,", body = { "Bois : pas assez. Péons : endormis. Deux sous le même arbre, un sur le tas de bois, et un debout. Je ne les savais pas capables de ça.", "Ils se souviennent de toi, en tout cas. Le bruit a couru que tu traînais dans la vallée avec ma masse. Depuis, dès qu'un péon entend des pas, il est debout, la hache à la main, avant même d'avoir ouvert les yeux. Ça ne dure pas. C'est mieux que rien.", "Ils demandent si tu vas revenir. Je leur dis que oui. Je ne leur dis pas quand.", "Bon travail. Merci pour le coup de main." }, signoff = "Thazz'ril\nContremaître" },
  [13] = { greeting = "$N,", body = { "La nuit où vous m'avez apporté la tête, je n'ai pas dormi. Je suis resté assis au bord de l'eau, à écouter. Aucun tambour n'est venu des îles. Derrière moi, le village dormait, tout entier, comme autrefois. Je voulais l'entendre dormir.", "Du rivage, on voit les îles de l'Écho. Je sais toujours quelle plage était la mienne. Les îles ne sont pas à nous. Je les regarde quand même.", "Certains de ceux que vous avez combattus étaient des Darkspear, avant le maléfice. Ne les pleurez pas. C'est à nous de le faire, et nous l'avons fait." }, signoff = "Gadrin" },
  [14] = { greeting = "Jeune $N,", body = { "Les bêtes se désaltèrent de nouveau au puits Sabot-d’Hiver, avec autant d'ardeur qu'au premier jour. J'ai regardé les trotteurs des plaines s'y pencher, et les loups y descendre après eux, et chaque fois j'ai pensé qu'ils buvaient une eau que leurs semblables ont aidé à purifier. Ils ne le savent pas, mais la terre le sait, et moi aussi.", "Chaque totem a demandé quelque chose aux bêtes de Mulgore, jusqu'aux crocs des loups alpha, et mon cœur en est encore lourd de mélancolie, et de fierté. Elles n'ont pas choisi de donner, et c'est vous qui avez porté leur don jusqu'aux puits.", "Quand le vent descend du nord, j'entends les esprits parler de vous." }, signoff = "Que les esprits soient avec vous,\nMull Thunderhorn" },
  [15] = { greeting = "$N,", body = { "Je vous écris pour accuser réception du rapport de Linnea, remis de votre main et sans délai. À Brill, la ponctualité est assez rare pour être remarquée.", "Le rapport disait ce qu'elle vous a dit. La Barricade contient le gros du Fléau, et quelques-uns passent quand même. Je l'ai classé avec tous ceux qui disent la même chose.", "Les fosses communes près de l'Antre de Garren ne sont pas sûres, mais les morts qui y reposent restent morts, et c'était bien là le but. Ils ont échappé à ce qu'on nous a fait subir. Il se trouve que j'ai un intérêt personnel à ce qu'il en reste ainsi, et votre travail chez les gnolls Poil-Putride l'a servi. Les apothicaires ont l'ichor. Ils ne m'en ont rien dit, ce qui, d'expérience, signifie qu'ils sont satisfaits.", "Le roi-liche et ses servants lancent des assauts incessants. Nous n'abandonnerons pas. Il ne passera pas." }, signoff = "Avec mes remerciements officiels,\nMagistrat Sevren" },
  [16] = { greeting = "$N,", body = { "La sentez-vous encore, cette vibration près des pierres dressées ? Oui ? Bien. Alors le lien est fait, et vous la sentirez de nouveau en bien des lieux.", "Les lignes telluriques vivaient autrefois dans les vieux livres. Aujourd'hui, elles percent l'herbe pour venir à notre rencontre. Don ou avertissement, c'est du savoir, et je compte bien en apprendre le plus possible avant que d'autres ne décident de ce que j'ai le droit de savoir.", "Rorian vous a remis votre relique en vous disant que les vents de votre patrie vous accompagneraient partout où vous iriez. Rorian y croit, et c'est une belle chose à croire. Je préfère ce qui se mesure.", "Ce sont des temps difficiles pour les Shen’dorei, et je sais ce que je veux d'abord : le savoir, puis le pouvoir." }, signoff = "Rendez l'inconnu connu,\nFalorne Tombevent" },
  [17] = { greeting = "$N,", body = { "La vue céleste est comme un muscle, et un muscle qu'on néglige s'affaiblit. Servez-vous-en sur la route, à l'auberge, sous la pluie. La plupart du temps, vous ne verrez rien qui vaille. Servez-vous-en quand même.", "Je garde la mienne ouverte un moment chaque soir, ici, au village, avant de dormir. Certains soirs, je saisis un mot ou deux, faibles comme une voix derrière un mur. D'autres soirs, rien. J'ai appris à ne pas en vouloir aux soirs silencieux. Ils font partie de l'entraînement.", "Je note ce que je saisis, même quand cela n'a aucun sens. Surtout dans ce cas. Les esprits ne se répètent pas pour nous faire plaisir.", "Nous aurons besoin de tous ceux qui savent écouter." }, signoff = "Patience,\nVentaari Vœu-Radieux" },
  [18] = { greeting = "$N,", body = { "J'ai envoyé Belathaan au sanctuaire d’Akir parce que la logique me le commandait. Parler coûte moins cher que saigner, et la paix moins cher que la guerre. Chaque ligne de ce raisonnement tenait. La secte y a répondu par une boîte. J'ai repris mes arguments bien des fois depuis, en cherchant l'erreur, et je ne la trouve que dans mon jugement sur la secte.", "Les Sculpte-vents avaient raison. L'écrire est pire que le dire.", "Les charmes que vous m'avez rapportés sont sous clé. Je les regarde moins qu'avant. Je n'ai pas oublié qui me les a rapportés.", "La secte a pesé notre prudence et l'a prise pour de la faiblesse. C'était un jugement, lui aussi, et le sien était bien plus erroné que le nôtre." }, signoff = "Elaadrin Trombecalme\nArchimagistère de l'Ordre suprême" },
  [19] = { greeting = "$N,", body = { "Je vous dois une meilleure réponse que celle que je vous ai donnée quand vous m'avez rapporté les charmes. « Une journée éprouvante », c'était bien peu dire.", "Les Sculpte-vents répondent au sang par le sang. Je l'ai dit toute ma vie, et je le pensais en vous envoyant au nord. Je le pense encore. Les novices que nous avons retrouvés dans les hautes-terres étaient des nôtres, et quelqu'un répondra de chacun d'eux.", "Mais je vous avais aussi demandé d'arrêter Belathaan sur la route, pour lui faire peur, et il n'est jamais revenu de cette route. Je vous ai dit que vous n'y étiez pour rien. C'était vrai. Je n'ai pas dit à qui revenait la faute, parce que je n'ai pas tranché. À Elaadrin, qui l'avait envoyé. À la secte, qui l'a tué. À moi, qui voulais qu'il ait peur. Sa mère était des nôtres.", "Ni oubli ni pardon. Lui non plus, je ne l'oublierai pas." }, signoff = "Ayessa Chantelaube\nGrande oracle des cieux des Sculpte-vents" },
  [20] = { greeting = "$N,", body = { "Le Barrage tient toujours ! Je descends à sa base chaque matin et chaque soir pour le regarder, et il tient toujours, et chaque fois je remercie les étoiles. Oh, ciel ! J'espère que vous ne saurez jamais ce que cette poudre aurait fait mouillée. J'en ai fait le calcul deux fois sur le papier, et puis j'ai arrêté de le faire !!", "Le détachement de sécurité est toujours sur le front de l'Alliance, et mon meilleur inspecteur avec lui. Il ne reste donc que moi, les montagnards qu'on veut bien me prêter, et l'eau. Maintenant, je frappe sur chaque tonneau que je croise. Sur chacun, sans exception.", "Personne d'autre n'est venu, et vous avez remué ce tonnelet comme on remue une soupe. Courage ou ignorance, je ne sais pas, et je vous suis reconnaissant de l'un comme de l'autre !", "Le Barrage est en sécurité, du moins pour l'instant, et tous ceux qui vivent en contrebas aussi." }, signoff = "Bien à vous, et un peu à la hâte,\nHinderweir VII\nIngénieur en chef, Barrage de Formepierre" },
  [21] = { greeting = "$N,", body = { "Pour une fois, voici une lettre de moi que vous n'aurez à porter nulle part.", "J'ai relu les trois réponses que vous m'avez rapportées plus souvent qu'un magistrat ne devrait relire quoi que ce soit. Hurlevent enverra des renforts dès que le roi en donnera l'ordre. La Marche de l'Ouest n'a pas d'hommes à offrir et a ses propres morts à enterrer. Sombre-Comté ne peut pas envoyer ses Veilleurs au-delà de la lisière de sa forêt. Chaque réponse est raisonnable. Ensemble, elles n'ont aucun sens.", "Comté-du-Lac tient, pour l'instant. Il y a de la trahison là-dessous, et je veux en avoir le cœur net. Bah. Je ne devrais pas réfléchir à voix haute, pas même sur le papier.", "Vous avez fait un long chemin pour un bourg qui ne vous devait rien, et chaque fois vous m'avez rapporté la vérité, même quand la vérité, c'était non. Merci." }, signoff = "Magistrat Solomon\nComté-du-Lac" },
  [22] = { greeting = "$N,", body = { "Hollee me dit que c'est vous qui m'avez fait sortir du chantier de fouilles, et que je n'étais pas, comme je le croyais alors, en train de me promener. Elle dit qu'il y avait des golems. Je me souviens d'une couche de sédiments tout à fait passionnante.", "Elle me dit aussi que mon fossile est allé à Darnassus, puis au Port de Menethil, ce qui fait plus de voyages que je n'en ai faits depuis des années, et qu'un certain Flagongut l'a maintenant, avec une pierre à lui. Formidable ! J'espère qu'il m'écrira. Qu'il m'écrira à moi, je veux dire, et pas à Hollee, même si c'est toujours Hollee qui semble tout recevoir.", "Je cherche mon pinceau à pierre. Je le mentionne seulement parce que je l'ai cherché pendant tout le temps où j'écrivais cette lettre, et qu'il m'a semblé impoli de ne pas le dire." }, signoff = "Avec mes remerciements et, je crois, mes excuses,\nProspecteur Remtravel" },
  [23] = { greeting = "$N,", body = { "Le NG-5 est arrivé en parfait état, c'est-à-dire qu'il ne t'a pas explosé à la figure en route, et je compte ça comme un succès pour tout le monde !", "Lomac est le meilleur chimiste qui m'ait jamais crié dessus. S'il t'a dit de me saluer, il le pensait. S'il a dit autre chose, il le pensait aussi, mais un peu moins.", "Tout est en place. Je ne te dirai pas le plan, d'abord parce qu'un plan raconté est un plan gâché, ensuite parce qu'il change chaque fois que je le regarde. Il y a des wagons. Il y a de la dynamite, qui n'est pas aussi dangereuse que tout le monde le croit. Il y a de la magie, des mixtures et de la mécanique qui travaillent ensemble, ce qui est tout l'intérêt de l'Assemblée et, franchement, de ma personne.", "Les elfes de la nuit me regardent encore comme si j'allais sauter. C'est de bonne guerre. Leur montrer qu'un gnome peut aider à sauver leurs forêts, c'est mon but, non, mon DEVOIR !" }, signoff = "Gaxim Rustfizzle\nAssemblée illuminée d'arcanologie, d'alchimie et de sciences d'ingénierie" },
  [24] = { greeting = "$N,", body = { "Le temps du deuil est venu, comme je l'avais dit, et il n'attend pas l'heure que j'aurais choisie. J'ai écrit à la famille de Teronis. C'est la lettre la plus courte que j'aie jamais écrite, et elle m'a pris toute la nuit.", "Vous l'avez trouvé, et vous avez trouvé ce qu'il cherchait en mourant. C'était plus que je n'osais espérer, et ce n'est pas assez.", "Les furbolgs n'ont pas toujours été nos ennemis. Quand j'étais jeune, je n'ai jamais tendu mon arc contre l'un d'eux. Aujourd'hui, je vous ai fait prendre la route de leurs camps et j'ai appelé cela défendre nos terres, et c'en était. Je veux seulement qu'il soit écrit quelque part que je me souviens d'un temps plus paisible." }, signoff = "Qu'Elune vous garde,\nRaene Wolfrunner" },
  [25] = { greeting = "$N,", body = { "J'ai prévenu la Grande prêtresse. Ce qui s'est dit entre nous, je le garde pour moi. Je dirai seulement que j'ai pris le chemin le plus long pour revenir au baraquement.", "Le coffre de Velinde est toujours dans le baraquement. Je ne parviens pas à le faire vider. Les Sentinelles croyaient qu'elle avait ses raisons de partir et qu'elle reviendrait quand elle le voudrait. Je le croyais aussi, et je vous l'ai dit. De toutes mes erreurs, c'est celle que j'aurais le moins voulu commettre.", "Cela me trouble de savoir que la Faux d'Elune n'est plus aux mains de ses servantes.", "Vous l'avez suivie à travers la moitié du monde sur la parole d'un livre qui s'écrit tout seul. Peu l'auraient fait. Je vous dois d'immenses remerciements." }, signoff = "Thyn'tel Bladeweaver" },
  [26] = { greeting = "$C,", body = { "Pardonnez ma colère, le jour de votre visite. Elle valait celle d'un kodo enragé, et vous n'aviez rien fait pour la mériter. La faute était mienne. J'ai envoyé des voyageurs sous la ville sans penser à qui d'autre pourrait les suivre, et deux amis ont payé ma négligence. Des sbires de Thrall, quels qu'ils soient. Je donnerais cher pour connaître leurs noms.", "En bas, je range ce que je peux. Nos amis des Tarides et de la forêt ont commencé leur propre ouvrage.", "Votre arrivée tombait au bon moment, et vous portiez la bonne marque. Je ne l'oublie pas. Dans une ville où si peu de gens sont ce qu'ils paraissent, il est réconfortant de connaître quelqu'un qui l'est." }, signoff = "Un ami de la Faille" },
  [27] = { greeting = "$N,", body = { "J'ai puisé ce que j'ai pu dans les chaînes de Bois-du-Bûcher que vous m'avez rapportées. Ce n'était pas assez. Je m'en doutais, et je crois bien l'avoir dit. Un petit échantillon reste un petit échantillon.", "Pourtant, je comprends le remède à présent, ou presque, et plus je le comprends, moins j'estime l'homme qui a jeté ce sort. Le Kirin Tor l'a laissé entrer dans ses salles. J'ai cessé de me demander comment.", "À Bois-du-Bûcher, ce sont toujours des hommes et des femmes le jour, et toujours autre chose quand le soleil se couche. Arugal a fait cela à tout un village avec un sort que n'importe quel apprenti aurait honte de signer. Ce que je lui pardonne le moins, ce n'est pas la malédiction. C'est la qualité du travail.", "Cela prendra plus longtemps que je ne pensais. Tout ce qui touche à Arugal prend plus longtemps que je ne pense. C'est peut-être son seul talent.", "Mes compliments, $N." }, signoff = "Dalar Dawnweaver\nLe Sépulcre" },
  [28] = { greeting = "$N,", body = { "Avant votre départ pour l'Ile de Fenris, j'ai rédigé deux rapports pour mes supérieurs. L'un disait que Thule Ravenclaw était mort. L'autre annonçait votre mort. Un commandant doit être prêt à l'un comme à l'autre. J'ai brûlé le second le jour où vous m'avez rapporté sa tête.", "Renferrel me dit que les énergies dégagées quand Thule est tombé ont été perçues jusqu'au Sépulcre. Il a raison. Je l'ai senti moi-même, et j'ai su ce que vous aviez fait avant qu'on me le dise.", "Le Fléau n'en a pas fini avec les Pins argentés. Les Poils-putrides tiennent toujours l'île, et ils ne la quitteront pas pour un mage mort. Mais ils ont perdu du terrain, et c'est par vous qu'ils l'ont perdu.", "Pour nous, votre valeur ne cesse de croître." }, signoff = "Grand exécuteur Hadrec\nLe Sépulcre" },
  [29] = { greeting = "$N,", body = { "Je ne suis pas doué pour les lettres. C'était elle qui avait les mots.", "Elle a tenu tête à trois hurans, à elle seule. Quand d'autres sont arrivés, j'en ai entraîné quelques-uns plus loin, et je me suis dit que c'était ça, le courage. Je ne me le dis plus.", "Le druide qui m'a trouvé sur la route m'a dit de me reposer. Je me suis reposé. Puis je suis retourné au camp où nous avions été séparés, et j'ai tué tous les hurans que j'y ai trouvés. Ça n'a pas aidé non plus.", "Vous l'avez trouvée, là où je n'ai pas pu. Je ne sais pas ce que vous avez vu là-bas, et je ne vous le demande pas.", "Merci, $C." }, signoff = "Mankrik" },
  [30] = { greeting = "$N,", body = { "J'ai dormi toute la nuit. Toute, du soir jusqu'à la première lumière sur la Cime des Anciens, et je me suis réveillée les mains ouvertes. J'avais oublié que le sommeil pouvait être si simple.", "Quand l'ancien a quitté le rêve, je suis restée, parce qu'il fallait que quelqu'un voie leurs visages. Je les ai vus. Ensuite, je n'ai plus pu cesser de les voir. Quatre visages, chaque nuit, tournés vers moi comme s'ils me connaissaient. Je me réveillais les poings fermés et les dents douloureuses. Ils ne viennent plus.", "Autrefois, ils étaient druides. Leur ordre voulait soigner les Tarides. J'y pense plus que je ne le voudrais. Il serait plus facile de les haïr s'ils avaient toujours été ce qu'ils sont devenus.", "La terre rêve encore, et mal. Ce n'était pas l'ouvrage d'une seule nuit. Mais mes rêves m'appartiennent de nouveau, et c'est vous qui les avez repris." }, signoff = "Nara Wildmane" },
  [31] = { greeting = "$N,", body = { "Les fortins ont tenu. Krom'zar a fait tout le chemin depuis Désolace pour se venger, et il est tombé sur vous.", "Barak, Verog, Hezrul, et puis Krom'zar. J'ai combattu les centaures presque toute ma vie, et je n'avais jamais vu quatre de leurs chefs tomber de la même main. Un centaure qui a l'esprit de mener les autres est rare, et ce sont ceux-là les plus dangereux. Vous avez pris les plus dangereux.", "Les Kolkar reviendront. Ils sont toujours revenus. Quand ils reviendront, ils se raconteront votre histoire, et j'espère qu'ils la raconteront mal.", "Gardez la tête haute, $N." }, signoff = "Regthar Deathgate" },
  [32] = { greeting = "$R,", body = { "Mangletooth écrit. <grogne> Mains pas faites pour la plume. Lisez quand même.", "Mangletooth a regardé votre course, depuis la cage. Vous couriez avec les zhévras. Le vent était jaloux, comme Mangletooth a dit. <grogne> L'esprit d'Agammagan répond encore à Mangletooth, barreaux ou pas. Aucune cage n'arrête ça. Souvenez-vous.", "Dos-hirsute plus faibles maintenant, grâce à vous et à Mangletooth. Et les Tranchecrins ne viennent toujours pas. Mangletooth a compté les jours. Puis Mangletooth a arrêté de compter. <grogne>", "Le contact des joyaux. Longtemps que Mangletooth n'en a pas tenu. Vous ne savez pas ce que c'est, quand on vous prive de votre pouvoir. Mangletooth espère que vous ne le saurez jamais.", "Mangletooth n'est pas un imbécile. Mangletooth est reconnaissant. Les deux. <grogne>" }, signoff = "Mangletooth\nCamp Taurajo" },
  [33] = { greeting = "$N,", body = { "Les gobelins abattent toujours les arbres de la Combe. Par vent d'ouest, je sens leur fumée jusqu'ici, à la frontière. Deux machines brisées ne leur apprendront rien, et je ne l'ai jamais cru.", "Mais la plupart des gémissements ont cessé. Pas le chagrin, les gémissements. Les esprits sont blessés, encore, et ils en ont bien le droit. Ils n'en sont plus aveuglés.", "Il se peut encore que les anciens doivent venir apaiser ce qui reste. Je vous l'ai déjà dit. Je vous le redis, pour que vous ne preniez jamais une victoire pour une forêt.", "Les esprits m'ont désigné ces machines. Vous leur avez parlé le seul langage que les gobelins comprennent. Je trouve le partage équitable." }, signoff = "Avec colère et avec espoir,\nSeereth Stonebreak" },
  [34] = { greeting = "$gChanceux:Chanceuse; $N,", body = { "Trente ! Trente précieux crânes, et tous plus beaux les uns que les autres ! Je les compte à chaque relève de la garde, au cas où l'un d'eux aurait roulé quelque part. Aucun n'a bougé. Ils sont très sages.", "Je les garde à l'abri des regards, là où Darthalia ne peut pas les voir. Elle estime qu'un Garde noir de service devrait monter la garde. C'est ce que je fais. Je les garde avec le plus grand soin.", "Il ne se passe jamais rien à ce poste. Pendant que vous vous amusiez comme jamais à Hautebrande, j'étais si jaloux que j'aurais pu tomber en morceaux, ce qui, à mon âge, est un vrai risque.", "J'espère bien que vous vous arrêterez à la porte en passant, ne serait-ce que pour que je puisse encore vous remercier." }, signoff = "Votre dévoué Garde noir,\nSamsa\nMoulin-de-Tarren" },
  [35] = { greeting = "$N,", body = { "Le port est ouvert. Des navires entrent, des navires sortent, et plus un équipage ne surveille les collines pendant qu'il s'amarre. C'est votre œuvre.", "Je vais vous dire ce que j'ai dit à Valstag. Un engin de siège, c'est patient. Ça attend dans les collines que vous preniez vos aises. Nek'rosh avait les siens qui nous attendaient, et vous avez mis un peu d'amadou à chacun d'eux. J'ai regardé la fumée depuis le rempart du donjon, et je n'ai pas dit un mot pendant un bon moment.", "Les Gueules-de-dragon n'en ont pas fini. Ils vont panser leurs plaies dans ces collines longtemps, et je les guette. Mais ils le feront face à un port toujours debout.", "$R de grand mérite, voilà ce que j'ai dit de vous. Je le redirais devant n'importe qui." }, signoff = "Capitaine Stoutfist\nPort de Menethil" },
  [36] = { greeting = "$N,", body = { "Chaque matin, je me rends à l'hôtel de ville en longeant des murs que la Guilde des Maçons a élevés après la guerre. Edwin en a posé certaines pierres lui-même. J'avais l'habitude de les montrer aux visiteurs. J'ai cessé.", "Vous m'avez apporté sa lettre jamais envoyée, puis vous l'avez suivie jusqu'à la Prison et au-delà. J'ai appris que le seigneur Lescovar avait été retrouvé mort. Je n'ai pas demandé comment, et je ne le demanderai pas. Je vous suis reconnaissant. Je le dis d'abord, parce que la suite est plus difficile à dire.", "Quand les nobles ont refusé de nous payer, on a offert des postes à certains d'entre nous. J'ai accepté le mien. Edwin a refusé le sien, par loyauté envers les autres, et il a juré de se venger. Je vous ai dit qu'il se moquait de qui il blessait, et que je n'étais pas sûr de pouvoir lui en vouloir. Je n'ai changé d'avis ni sur l'un ni sur l'autre.", "La cité tient debout, et je garde ses plans. Certains matins, cela ressemble à une réponse que je lui fais, et d'autres matins, au poste qu'il n'a pas voulu prendre." }, signoff = "Baros Alexston\nArchitecte de la cité" },
  [37] = { greeting = "$N,", body = { "Je suis retourné à la ferme. C'est la première fois depuis cette nuit-là. La grange est toujours debout, et la vieille souche où le livre était enterré aussi. Je suis resté là un long moment. Puis je suis revenu à mon camp, et j'ai dormi.", "Morbent Fel est vaincu. Les Cavaliers noirs ne le sont pas, et je ne ferai pas semblant du contraire. Mais une petite part de ce que je n'espérais plus s'est réalisée, par votre main et par cette lame venue de Hurlevent.", "Je sais qui est la Tremblotte, maintenant. Il a vu mourir ma famille sans rien pouvoir faire, et il a tout écrit parce qu'il ne pouvait pas le porter seul. Je découvre que je ne peux pas haïr un homme pour ça. J'essaie de ne pas le haïr.", "Peut-être qu'un jour, le destin vous ramènera vers moi. Je le pense comme je le pensais alors." }, signoff = "Sven Yorgen" },
  [38] = { greeting = "$N,", body = { "J'ai de nouveau tiré les cartes pour Alyssa. La Faucheuse n'est pas sortie. Ce qui est sorti, c'est une carte que je n'avais pas vue depuis longtemps, une carte banale, sans la moindre importance. Elle annonce une journée ordinaire. Je suis restée à la regarder jusqu'à ce que mon thé refroidisse.", "Vous avez suivi un nom sorti de ma transe jusqu'au registre, jusqu'à Ruisselune, Comté-de-l’Or et Hurlevent, puis retour, et chaque porte où vous frappiez s'ouvrait sur quelque chose de plus ancien et de pire. Cette route, c'est moi qui l'ai tracée pour vous. Je suis désolée pour une partie de ce que vous avez trouvé au bout.", "La forêt est toujours sombre. Les cartes le disent, et elles se trompent rarement au sujet du bois de la Pénombre. Mais il y a une ombre de moins sur cette maison.", "Alyssa ne sait pas à quel point le danger était proche, et je compte bien qu'elle ne le sache jamais." }, signoff = "Madame Eva" },
  [39] = { greeting = "$N,", body = { "Je vous écris de la Combe de Nijel, mes bagages prêts pour Darnassus. Vahlarriel dit que je pourrai partir quand je serai prête. Je trouve sans cesse de petites raisons de ne pas l'être encore.", "Je vous ai dit merci pour la mort de mon frère. J'y ai pensé plus qu'à tout ce que les orcs m'ont fait. Je le pensais, et je ne le pensais pas, et les deux restent vrais. Si ce n'avait pas été votre main, c'est l'un des miens qui aurait frappé. C'est une maigre consolation, mais c'est la seule que j'aie.", "Mon père me demandera ce que Tyranis cherchait ici. Je lui dirai la vérité : le savoir, plus qu'il n'était bon pour lui, plus que notre peuple ne le permet. Je ne lui dirai pas comment cela a fini.", "Vous m'avez fait sortir de cette forteresse, et vous m'avez laissée marcher seule jusqu'au bout. C'est ce dont je me souviendrai le mieux." }, signoff = "Dalinda Malem" },
  [40] = { greeting = "$N,", body = { "Quae dit que je m'inquiète trop. Quae a raison, et ça ne m'a jamais arrêté. Alors, maintenant que je sais mes deux trouble-fête en vie, je me suis trouvé quelqu'un d'autre pour qui m'inquiéter. Vous.", "J'ai lu ce que Kin a rapporté de cette ferme. Je le lis la nuit, ce qui est une mauvaise habitude, parce que ce n'est pas le genre de lecture qui aide un homme à dormir. Quoi que Jorell soit en train de concocter là-bas, je mettrais ma main au feu que Stanley y est pour quelque chose.", "Mon cousin refuse toujours de parler de ce chien. Je ne lui en veux pas.", "Bref. Mangez chaud, gardez le dos contre un mur, et buvez moins que Kin." }, signoff = "Phin Odelic\nAustrivage" },
  [41] = { greeting = "$gCher client:Chère cliente;,", body = { "Au sujet de votre récente demande. La meule que vous cherchiez a quitté Menethil par bateau bien avant que vous ne commenciez à poser des questions, comme vous l'avez appris sur place. Notre ami du port vous salue et dit que l'animation lui manque, ce qu'il m'a demandé de ne pas répéter, alors je vais faire comme si je ne l'avais pas écrit.", "Le reste de la commande est désormais entre les mains de nos amis de Theramore, et ce sont des gens prudents. Que la meule refasse surface ou non ne dépend plus de moi.", "Je dirai une chose clairement. Vous avez fait plus de chemin que je ne vous en ai payé, et pas un mot de tout cela n'est arrivé jusqu'à ma boutique par quelqu'un d'autre que vous. Je l'ai remarqué. Je remarque presque tout." }, signoff = "Avec mes remerciements pour votre fidélité,\nElling Trias\nMaître fromager, quartier commerçant" },
  [42] = { greeting = "$N,", body = { "J'ai envoyé Caldwell à la Halte perdue, comme je l'avais dit. Les marais ne sont pas si grands qu'un homme puisse s'y cacher pour toujours, même si Reethe semble décidé à essayer.", "Jim sourit toujours à tout le monde. Je m'arrête pour bavarder avec lui quand je peux. Il parle de l'auberge comme si elle était encore debout au bord de la route, et je le laisse faire.", "Ce n'est jamais bon signe quand on m'apporte l'insigne d'un garde. Celui de Reethe était de la pire espèce : un homme si loyal envers le vieil amiral qu'il a tourné le dos à son serment, puis trop imprudent même pour les déserteurs avec qui il s'était enfui. Ce sont eux qui nous traitent de traîtres. Je leur accorde l'ironie.", "Balos Jacken vous a demandé d'oublier que vous les aviez trouvés. Je vous en prie, n'en faites rien." }, signoff = "Capitaine Garran Vimaire\nTheramore" },
  [43] = { greeting = "$N,", body = { "Je suis le magistrat d'une ville de pêcheurs. Je règle des querelles de filets et de bornes, et de temps à autre celle d'un ivrogne qui a pris la porte d'un autre pour la sienne. Je n'étais pas fait pour des noms comme la Veille d'Argus.", "Dibbs a fouillé chacun de ses livres pour la trouver, et il n'a rien trouvé.", "Vous avez réglé leur compte aux mages des Hauteurs, et le Syndicat en est appauvri. J'aimerais que ce soit la fin. Mais celui que servait Nagaz est toujours quelque part, plus loin que les montagnes d'Alterac, et je suis un homme qui aime savoir où logent ses inquiétudes.", "Alors le soir, je regarde vers le nord, là où je regardais la mer. Merci de m'avoir apporté ce que je ne voulais pas savoir. Mieux vaut moi qu'un autre." }, signoff = "Magistrat Henry Maleb\nAustrivage" },
  [44] = { greeting = "$N,", body = { "La Tablette de volonté est entre les mains des mages du roi, sous plus de serrures que je n'ai de clés. Ce qu'ils en apprendront, c'est à eux de le dire. Ce que je peux dire, moi, c'est qu'elle n'est jamais tombée aux mains des Ombreforge, et qu'elle a été le rêve de Hammertoe bien avant d'être l'affaire de qui que ce soit.", "Karnik me dit qu'il a parlé avec l'esprit de Hammertoe. Je suis conseiller, pas prêtre, et je ne sais pas trop qu'en penser. Mais il dit que Hammertoe est en paix, et j'ai décidé de le croire.", "Och. Un nain qui a passé sa vie à chercher d'où venait notre peuple, et ses dernières années à empêcher que de mauvaises mains ne le découvrent avant lui. Je n'en aurais pas fait la moitié, à sa place ou à la vôtre.", "Voilà une vie qui vaut la lettre d'un conseiller, et c'est grâce à vous qu'elle n'a pas été vaine." }, signoff = "Conseiller Belgrum\nForgefer" },
  [45] = { greeting = "$N,", body = { "Vous avez arraché la Vue de l'esprit aux mains de Mai'Zoth, et la première chose que j'ai décidée, c'est de ne pas regarder dedans. Un homme qui cherche à savoir si une chose peut servir le Bien ne devrait pas commencer par la laisser se servir de lui.", "Elle est enveloppée et rangée. Je prie à côté d'elle, et je lis ce que d'autres ont écrit sur ces choses-là. S'il y a du bon en elle, je le trouverai. Sinon, elle sera détruite, et je ne la pleurerai pas.", "Je pense souvent au colonel Kurzen tel qu'il était, un homme grand et noble. Les légendes, les fétiches, tout désignait une seule vérité : ce qui l'a brisé venait de l'extérieur. C'est un réconfort, et aussi un avertissement. Cela aurait pu arriver à n'importe qui.", "Puisse votre force ne jamais faiblir, $N." }, signoff = "Frère Nimetz\nCamp rebelle" },
  [46] = { greeting = "$N,", body = { "Comment va votre petite fée ? Je me pose la question, et un vieux dresseur a bien le droit de se la poser.", "Quelques conseils qui méritent d'être répétés, avec cet œuf qui a éclos plus tôt que prévu. Les fées fléchetteuses mangent de la viande et de la verdure, alors ne laissez personne vous dire le contraire. Des flancs crus, attention, et en quantité.", "Ah, les petits ! Un instant, vous courez à travers le monde avec un œuf et une heure devant vous, et l'instant d'après vous voilà $gpapa:maman;. Ou presque.", "Ha ! Ha ! Prenez bien soin de vous, et de la petite aussi, si vous l'avez gardée." }, signoff = "Agnar Beastamer\nNid-de-l'Aigle" },
  [47] = { greeting = "$N,", body = { "Bec-tranchant a volé avec toute l'escadre pour la première fois. Il était trop loin sur la gauche et bien trop fier de lui, et sa mère a dû le remettre dans le rang deux fois. C'est la plus belle chose que j'aie vue sur ce pic depuis bien des années.", "J'ai fait prévenir Thadius au Rempart-du-Néant, pour la part qu'il y a prise. Il est parti il y a longtemps à la poursuite d'un savoir plus sombre, et certains ici refusent encore de prononcer son nom. Mais c'est sa vision qui a retrouvé le petit, et dans son cœur, c'est encore un Wildhammer.", "Les cavaliers en font une chanson. Elle n'est pas bonne. Les chansons des Wildhammer ne le sont jamais, la première année. Ils la chanteront quand même, longtemps, et votre nom est dans tous les couplets qu'ils ont trouvés jusqu'ici." }, signoff = "Maître des gryphons Talonaxe\nNid-de-l'Aigle" },
  [48] = { greeting = "$N,", body = { "C'est Emma Felstone qui écrit. Je me suis remise à signer de ce nom, après toutes ces années. C'est comme un manteau oublié chez quelqu'un.", "J'ai passé en revue tout ce que Janice m'a envoyé. De vieilles lettres. Une recette de Mère que j'avais oubliée. Le titre de propriété de la ferme, rien que ça, comme si j'allais jamais y retourner. Elle a toujours fait ses bagages comme si elle s'installait pour de bon.", "J'ai cru que vous pilliez des tombes. Je le dirai une fois, simplement, et puis nous n'en parlerons plus. Je suis désolée.", "Si ce charme a fait ce que j'espérais, alors elle se repose, et elle n'attend plus de livraison. S'il ne l'a pas fait, ne me le dites pas. Je préfère penser que si." }, signoff = "Emma Felstone" },
  [49] = { greeting = "$N,", body = { "Je ne comprends pas pourquoi le Chef de guerre tient tant à une si petite chose. Une petite chaîne, une petite pierre. J'ai vu des guerriers mourir pour moins que ça, et pour plus, et je ne sais pas de quel côté elle se trouve. Je l'ai tout de même envoyée à Orgrimmar, cousue dans le sac d'un messager. Je lui obéis. Cela m'a suffi jusqu'ici, et cela me suffit encore.", "Gol'dir vous a dit qu'il rentrerait par ses propres moyens une fois ses affaires réglées, et je le crois. C'est un orc de parole.", "Quant à la fille, j'espère qu'elle est partie loin de ce manoir. On l'y retenait contre sa volonté, comme on retenait nos guerriers à Fort-de-Durn. Je suis content que personne ne lui ait fait de mal." }, signoff = "Krusk\nMoulin-de-Tarren" },
  [50] = { greeting = "$N,", body = { "Un autre jeune s'est tenu sur les planches au-dessus du canyon et n'a pas pu sauter. Je ne l'ai pas poussé. Une foi qu'on pousse n'est pas une foi.", "Je lui ai dit ce que je vous avais dit : l'esprit, le corps, l'âme. Ces trois choses ont été éprouvées chez vous, et aucun de nous ne vous a facilité la tâche. Parqual croyait à une imposture. Braug craignait que vous oubliiez vos lectures. Moi, j'ai toujours cru que vous sauteriez.", "Vous avez passé ma porte, et à votre retour, vous aviez changé. Vous aviez trouvé l'équilibre, et c'est plus rare que la force.", "Gardez l'équilibre." }, signoff = "Dorn" },
  [51] = { greeting = "$N,", body = { "Qu'un ogre maladroit, armé d'une simple couronne, ait échappé si longtemps à la volonté de la Dame noire me trouble davantage que si elle avait été d'or. Un grand pouvoir devrait au moins avoir la décence d'en avoir l'air.", "La Couronne a été remise. Je l'ai portée moi-même à la Dame noire, et j'avoue que je la tenais un peu à distance, comme on porte une chose qui pourrait mordre.", "Elle a eu vent de votre part dans cette affaire. J'y ai veillé, comme je l'avais promis. Votre nom a été prononcé dans le Quartier royal, ce que bien peu de vivants peuvent dire." }, signoff = "Sharlindra" },
  [52] = { greeting = "$N,", body = { "Vous pardonnerez la longueur de cette missive. Chez les miens, une longue phrase passe soit pour un signe de génie, soit pour le symptôme d'une maladie, et j'ai choisi d'être tenu pour un génie.", "Mok'Morokk a fui comme un lapin, et bien qu'il soit depuis revenu bouder parmi nous, personne à Mur-de-Fougères ne l'a oublié. Le clan délibère à présent sur sa succession. Les ogres délibèrent à la manière d'un éboulement : lentement, bruyamment, et avec des blessés. Tharg ferait un chef admirable, s'il était plus jeune et moins brisé.", "Pendant ce temps, la progéniture d'Onyxia demeure au sud, et je demeure le seul, à Mur-de-Fougères, à se soucier de savoir pourquoi. Votre besogne parmi les œufs nous a fait gagner du temps. J'entends l'employer avec sagesse, ce qui, dans ce village, fait de moi une manière d'excentrique." }, signoff = "Avec ma très haute considération,\nDraz'Zilb" },
  [53] = { greeting = "$N,", body = { "Les savants ont le pendentif, et ils sont lents, comme doivent l'être les savants. Je l'ai moi-même regardé bien des fois. Les humains mettent plus d'eux-mêmes dans un bijou qu'un orc dans une épée.", "Ce qui me revient sans cesse, c'est l'espion qui l'a dérobé. Il a surveillé Theramore des semaines durant, seul, puis il a pris le pendentif lors de sa dernière nuit, et un Bourbecoque l'a tué sur le chemin du retour. Il n'a pas achevé sa mission. Vous l'avez achevée pour lui. Si les esprits accordent le repos pour de telles choses, le sien devrait l'avoir.", "Un prophète apprend à attendre, et j'attendrai le pendentif aussi longtemps qu'il le faudra. Notre espion n'a pas eu ce luxe. Je suis heureux qu'il ait pu compter sur vous." }, signoff = "Zor Lonetree" },
  [54] = { greeting = "$N,", body = { "La ruse du raptor s'est dissipée, comme je savais qu'elle le ferait. Ensuite, Gor'mul et moi avons parlé, comme je l'espérais.", "Il a écouté. Il n'a pas souri, et je ne le lui ai pas demandé. Il m'a demandé si le jeune Chef de guerre porte vraiment l'armure d'Orgrim et son marteau, et je lui ai dit que oui. Il est resté longtemps silencieux après ça. Puis il a voulu savoir ce que les chamans savent faire aujourd'hui, je lui en ai montré un peu, et cette fois, il n'a rien jeté par terre.", "Ce n'est pas un guerrier revenu. Mais c'est un guerrier qui a posé une question, et de toutes les années où il a erré seul, je ne crois pas qu'il ait jamais rien demandé à personne.", "Vous lui avez fait faire une partie du chemin du retour, $N, et le reste du chemin lui appartient." }, signoff = "Tor'gan\nTrépas-d'Orgrim" },
  [55] = { greeting = "$N,", body = { "Trol'kalar est en route pour Nimboya, à Grom'gol, enveloppée dans trois étoffes et portée par deux de nos plus rapides, parce qu'aucun des deux ne voulait laisser l'autre la porter seul.", "Vous savez ce que signifie ce nom. Tueuse de trolls. Pendant des générations, les hommes de Strom et d'Arathor l'ont brandie contre mon peuple, et les grands-pères de nos grands-pères ont appris à fuir rien qu'en la voyant. Aujourd'hui, un troll l'a tenue. Moi, je l'ai tenue. Mes mains tremblaient, et je n'ai pas honte de le dire.", "On en aura besoin là où les nôtres se battent, dans les forêts brumeuses de Zul'Gurub. Si elle se souvient du camp pour lequel on l'a forgée, je ne saurais le dire.", "Si elle est entre nos mains, c'est grâce à vous, $N." }, signoff = "Zengu\nTrépas-d'Orgrim" },
  [56] = { greeting = "$N,", body = { "Le chef m'a envoyé de l'autre côté de la mer pour retrouver son plus jeune fils, et je le lui ramènerai moi-même. Pas tel qu'il est parti. Dans une gemme pas plus grosse que mon poing, lui, enfin libéré de Zanzil. C'est plus que je n'osais espérer quand je comptais les têtes des Bloodscalp près du chaudron.", "Le Grand Serpent lui a épargné la hache des chasseurs de têtes, et vous lui avez épargné le reste. Une âme retenue si longtemps ne se réveille pas d'un coup. Les Darkspear savent être patients. Nous avons traversé toute une mer autrefois, et nous sommes revenus pour lui.", "Nos chants porteront votre nom. La pierre, je la laisse aux graveurs." }, signoff = "Nimboya\nCampement Grom'gol" },
  [57] = { greeting = "$C,", body = { "Les fétiches ne sont plus que cendres. Je les ai brûlés moi-même au bord du Bassin des larmes, en me tenant face au vent. Ce qu'ils contenaient a mis longtemps à cesser de fumer.", "Je repense sans cesse à cet exilé dans les Hinterlands. Il a regardé la prophétie de son grand prêtre et il a dit ce qu'il voyait, alors on a écrit sa sentence avec du sang sur de la peau séchée et on l'a envoyé vivre chez les Witherbark. Chaque armée où j'ai servi avait un homme comme lui. La plupart avaient raison.", "Jammal'an croit toujours que son dieu rendra les Atal'ai immortels, et les dragons verts surveillent les eaux en attendant le jour où il essaiera." }, signoff = "Fel'zerul\nPierrêche" },
  [58] = { greeting = "$N,", body = { "Le camp tient, et les Griffebois l'attaquent moins souvent, à ce que disent mes sentinelles. Pendant des années, je les ai pris pour de simples sauvages. Votre carte m'a montré le contraire. Ils se battaient sur deux fronts, et celui du sud était celui qui les épuisait. Quelque chose les poussait vers le nord, et nous étions sur leur chemin.", "J'ai étudié les glandes que vous avez prises sur Fouet-cuisant jusqu'à pouvoir les dessiner de mémoire. Ce qui vit dans le Gouffre grouillant est organisé, patient, et plus proche que je ne le voudrais. C'est à moi de veiller à ce que nous tenions assez longtemps pour en tirer des leçons.", "Pour la première fois de ma vie, j'ai pitié d'un gnoll, et j'aurais préféré continuer à les haïr." }, signoff = "Hadoken Swiftstrider\nCamp Mojache" },
  [59] = { greeting = "$N,", body = { "Ha ! Le vaisseau est prêt, et les matériaux que vous m'avez apportés valent mieux que ce que j'avais demandé. Bûches fendues de tréant, minerais incrustés de géant, tendons résistants de chouettard, tous ces petits fragments de métal. J'ai trié chaque morceau moi-même, à l'odeur.", "Neeru dit qu'il est très content de la tête. Un bon client, celui-là. Il ne pose pas de questions, et il paie en herbes.", "Ce que les miniatures et le vaisseau donneront ensemble, c'est mon affaire, et celle des esprits. Mais je vous dirai ceci. Quand j'ai mis le dernier fragment, toute la hutte s'est tue, comme une jungle se tait quand quelque chose de gros écoute.", "Vous avez de bonnes mains pour la cueillette, $N, et un sorcier-docteur remarque toujours les mains." }, signoff = "Sorcier-docteur Uzer'i\nCamp Mojache" },
  [60] = { greeting = "$N,", body = { "Vous avez durement travaillé dans cette neige. Quatre sortes de chouettards, chacune pire que la précédente, et vous les avez tous vaincus.", "Je n'ai jamais vu le Berceau-de-l’Hiver que depuis l'entrée des tunnels des Grumegueules, blanc et silencieux. Vous en avez vu plus que moi. Si nos routes se croisent, j'aimerais que vous me racontiez à quoi ressemblaient ces grottes du sud.", "Quel genre de secret peut rendre fous ses propres gardiens ? Je tourne la question dans ma tête chaque soir depuis le retour des messagers. Ce que les elfes de la nuit ont laissé là-bas n'a pas été laissé pour nous, et c'est justement pour ça que nous devons le savoir." }, signoff = "Trull Failbane\nPoste de la Vénéneuse" },
  [61] = { greeting = "$N,", body = { "Oserai-je le redire ? Un triomphe ! Je l'ai dit à tous ceux qui, à la Barricade, voulaient bien rester immobiles pour l'entendre.", "J'aime les plans qui marchent, et le nôtre a marché trois fois. On me dit que la Croisade a trouvé notre bannière et s'est jetée sur le Fléau, exactement comme prévu. Les tours se sont allumées sur les traqueurs de mes prêtres comme des balises sur une carte. Et puis vous avez pénétré dans Andorhal et vous m'avez rapporté un éclat du phylactère d'Araj, la seule partie dont aucun de mes plans ne peut s'attribuer le mérite.", "Le Fléau ne renoncera pas à Andorhal pour une liche tombée, et je ne vous ferai pas l'insulte de prétendre le contraire. Mais il se souviendra de qui a lancé la Croisade contre lui, de qui a marqué ses tours, et de qui a franchi ses portes ensuite." }, signoff = "Grand exécuteur Derrington\nLa Barricade" },
  [62] = { greeting = "$N,", body = { "Je suis toujours Payson. Je tiens à ce que ce soit compris avant toute chose. J'ai pris ce nom après m'être réveillé dans cette glorieuse non-vie, et un colis venu d'une morte n'y changera rien.", "Je vous ai dit que vous étiez un vrai vautour. Vous n'en étiez pas un, finalement, et je découvre qu'avoir tort me dérange moins que je ne l'aurais cru.", "Mais j'ai gardé ce qu'elle m'a envoyé. Tout. C'est dans une boîte sous les caisses de cafards, là où personne ne pensera à regarder, et c'est un peu le but." }, signoff = "Jeremiah Payson\nVendeur de cafards" },
  [63] = { greeting = "$N,", body = { "Toujours le dix-huitième pilote ! Je sais. Je suis aussi surpris que vous.", "Le lance-hydroglycérine est parti exactement comme Shreev l'avait dit, c'est-à-dire d'un seul coup. Le record ? Pulvérisé. Avec deux caisses et la plupart de mes sourcils. Les sourcils repoussent.", "Je voulais regarder les gnomes me regarder. Raté. Trop vite. C'est le problème quand on en veut toujours plus : on rate le paysage.", "Pozzik est déjà en train de bricoler le nouveau régulateur en marmonnant des histoires de sûreté.", "Merci pour toutes ces courses, $N. J'étais occupé à aller vite." }, signoff = "Razzeric\nLes Salines" },
  [64] = { greeting = "$N,", body = { "Un petit mot, car je suis au beau milieu de quelque chose. Je suis toujours au beau milieu de quelque chose.", "Les brassards de liaison de pierre m'ont été inestimables. Deux d'entre eux, du moins. Servo a égaré les trois autres, ce qui est précisément la raison pour laquelle je vous en avais demandé cinq, ce qui prouve assez bien la méthode.", "Les liaisons avancent. Une fois terminées, un mage pourra lier des élémentaires d'une force que personne n'a jamais liée, à condition que le coefficient se tienne tranquille, ce qu'il fera, maintenant que j'ai tenu compte du sable.", "Lucien me dit qu'il vous a fabriqué quelque chose avec les pierres qui restaient. Je l'aurais fait moi-même, bien sûr, si j'y avais pensé, ce qui n'a pas été le cas, puisque je pensais aux liaisons." }, signoff = "Avec ma gratitude, et à la hâte,\nLotwil Veriatus" },
  [65] = { greeting = "$N,", body = { "La terre a votre nom dans la bouche, maintenant. C'est un bon nom.", "Vous avez abattu le khan Hratha. Vous avez abattu le khan Jehn. Les Magram sont déjà faibles. J'entends encore geindre leurs ventres quand le vent est bon. Je ris chaque fois.", "Le cristal rouge reste chaud dans mes mains, la nuit. Ma magie est forte, maintenant, plus forte qu'aucun khan ne le croyait. Ils se fiaient à leur force. Ils n'écoutaient pas la terre. La terre se souvient de ceux qui n'écoutent pas.", "Votre nom est déjà prononcé autour de nos feux. La terre le connaît, et j'écouterai." }, signoff = "Uthek la Sage" },
  [66] = { greeting = "$N,", body = { "Entre amis, donc.", "Le dernier lot est parti pour les Salines, et on me dit que les équipes des stands sont restées très silencieuses un jour ou deux. Pendant ce temps, un bon nombre de gens, ici, au port, semblent me devoir un verre, et j'ai cessé de payer les miens.", "La Mixture de Zanzil fait de drôles de choses à la levure. De drôles de choses aux gens aussi, mais la levure, c'est mon métier, et à votre place, je m'en tiendrais là.", "Voici ce qui me plaît chez vous. Vous avez porté un projet louche d'ici jusqu'aux Salines et retour sans jamais demander à quoi il servait. Je vous ai donné un petit extra pour ça, à l'époque. Cette lettre n'est pas un paiement. Prenez-la comme un compliment, de la part de quelqu'un qui n'en fait guère." }, signoff = "Crank Fizzlebub" },
  [67] = { greeting = "$N,", body = { "Des millions ! Enfin. Des milliers, presque. Enfin, un nombre très encourageant de centaines, et ça monte !", "Le fabuleux Élixir Noggenfogger se vend mieux que tout ce qui n'est pas de l'eau à Gadgetzan. Les clients en redemandent, et c'est la marque d'un produit de qualité. Certains reviennent un peu plus petits, ou un peu plus osseux, ou en flottant doucement vers le sol, mais ils reviennent, et c'est ce qui compte.", "Sprinkle raconte à qui veut l'entendre que je lui dois une faveur. Drôle de femme. La poudre, c'était son idée, d'accord, mais le génie, c'était de bien remuer.", "Vous étiez là au tout début, $N, quand ça avait le goût de l'intérieur d'une glande de rosée, et je m'en souviendrai quand je serai célèbre." }, signoff = "Marin Noggenfogger\nGadgetzan" },
  [68] = { greeting = "$N,", body = { "Ça me revient par morceaux. Une odeur de sel. Un grand champ au bord duquel je crois avoir grandi. Une chanson que quelqu'un fredonnait en affûtant des lames. Rien de tout ça n'est dans l'ordre, ni très utile, mais tout ça est à moi.", "La Flamme dorée rentre chez elle, là où on pourra la protéger. Je me souviens du chemin, maintenant. C'est nouveau.", "Je vous ai donné un conseil, un jour : c'est dangereux d'y aller seul. J'aurais bien fait de le suivre moi-même.", "Sans vous, j'errerais encore dans ce cratère à demander mon propre nom aux inconnus." }, signoff = "Linken\nRefuge des Marshal" },
  [69] = { greeting = "$N,", body = { "Je vous regardais, vous savez. Quand le dernier brasero s'est éteint dans le Fort des ombres, mes sorts ont pu voir à nouveau, et la première chose qu'ils m'ont montrée, c'est vous, debout dans la fumée. J'ai observé bien des choses par divination dans ma vie. Je ne crois pas avoir jamais été aussi heureuse de voir l'une d'elles.", "Islen m'a fait porter ses amitiés avec l'eau, et un avertissement que je ne cesse de retourner : ce que je poursuis est plus grand que je ne le sais, et je l'apprendrai bien assez tôt. Elle se trompe rarement. Le Conseil a été frappé à la tête à Jaedenar, mais un serpent comme celui-là en a plus d'une.", "Gangrebois est toujours malade, et le restera longtemps encore. Mais il l'est un peu moins dans un coin sombre, et la Terre-mère le voit, même là où personne d'autre ne le voit." }, signoff = "Que la Terre-mère vous garde,\nGreta Mosshoof\nSanctuaire d'émeraude" },
  [70] = { greeting = "$N,", body = { "Depuis que je les connais, mes amis ont toujours été les plus malins. Legacki, Sprinkle et sa cuisine, Quixxil et ce que fait Quixxil, quoi que ce soit. C'étaient mes idées à moi dont on riait, alors je les gardais dans ma poche.", "Plus maintenant ! Le yéti est rentré à la maison, un peu roussi à une oreille, et chaque fois que je le regarde, je me dis : c'est moi qui ai fait ça. Un yéti entier. À partir d'un dessin.", "Ils m'ont tous répondu, d'ailleurs. Je ne vous dirai pas ce qu'ils ont écrit, puisque vous étiez là pour presque tout. Mais deux d'entre eux m'ont demandé comment il marche, et c'est le passage que je relis sans arrêt.", "Vous avez transporté un yéti mécanique à travers la moitié du monde pour moi, $N. Personne n'avait jamais rien fait d'aussi farfelu pour me faire plaisir. Merci." }, signoff = "Umi Rumplesnicker\nLong-Guet" },
  [71] = { greeting = "$N,", body = { "Je dors mal depuis que vous m'avez apporté ce livre. Les Annales de Darrowshire. Ma patrie, écrite par quelqu'un qui n'y était pas, puis prolongée par quelque chose que je ne comprends pas.", "Elles disent que mon frère Joseph a changé de camp. Qu'il a été corrompu, qu'il a trahi les défenseurs, et qu'ils en sont morts. J'étais l'un des défenseurs. J'ai survécu. Avant de lire ce livre, je ne savais pas qui nous avait trahis.", "Le crâne et l'épée brisée sont sous clé. Je n'aime pas ce que je ressens quand je les touche, alors je ne les touche pas.", "Joseph avait une fille. Je ne me suis pas permis de penser à elle depuis des années." }, signoff = "Carlin Redpath\nChapelle de l'Espoir de Lumière" },
  [72] = { greeting = "$N,", body = { "Mon fils vous a parlé de son rêve, où je me tenais enfin à ses côtés dans l'Ordre. Il voulait que ce rêve cesse.", "Je rêve, maintenant. Le même rêve, je crois. Je me tiens à ses côtés. C'est un petit garçon avec un marteau de jouet, puis c'est un homme dans son armure, et puis il n'est plus là. Je me réveille avant la fin. La Lumière est miséricordieuse, au moins en cela.", "L'Ordre renaît. Je n'aurais pas voulu le relever ainsi. Mais Taelan avait jeté son étendard à terre, une fois, vous le lui avez rapporté, et je ne le laisserai pas tomber une seconde fois." }, signoff = "Tirion Fordring" },
  [73] = { greeting = "$N,", body = { "On me dit que les vôtres, quand ils sont reconnaissants, écrivent. Des marques sur une peau mince, pliée et portée de main en main. C'est une façon bien lente de dire ce qu'une marée dit en une fois. Mais vous nous avez rapporté les mains de quatre capitaines du feu, alors j'essaierai votre manière.", "Je ne comprends pas comment les vôtres mesurent la gratitude. J'observe les mortels depuis longtemps, et je les ai vus se remercier pour de toutes petites choses : une porte tenue, une coupe remplie. Ce que vous avez fait n'était pas une petite chose. J'ignore quelle taille doit avoir une lettre, chez vous, pour une chose aussi grande.", "Celle-ci devra suffire. La guerre continue. Mais votre nom a parcouru les chambres des Seigneurs des eaux." }, signoff = "Duc Hydraxis" },
}
-- (the places Classic Era's client names otherwise, swapped in there)
ns.classicNames = { ["Hurlevent"] = "Stormwind", ["Cabestan"] = "Ratchet", ["Sabot-d’Hiver"] = "Winterhoof", ["Comté-du-Lac"] = "Lakeshire", ["Sombre-Comté"] = "Darkshire", ["Fossoyeuse"] = "Undercity", ["Hautebrande"] = "Hillsbrad", ["Comté-de-l’Or"] = "Goldshire", ["Austrivage"] = "Southshore", ["Forgefer"] = "Ironforge", ["Fort-de-Durn"] = "Durnholde", ["Pierrêche"] = "Stonard", ["Berceau-de-l’Hiver"] = "Berceau-de-l'Hiver", ["Long-Guet"] = "Long-guet" }
